/*START - header nav link underline by WB */
nav#global-navbar{
    a.navigation__link {
        text-transform: uppercase;
        position: relative!important;
        &:before, &:after{
            transition: 0.4s;
            text-decoration: none!important;
            line-height: 1;
            content: """";
            height: 1px;
            position: absolute!important;
            bottom: 0;
            left: 0;
        }
        &:before {
            width: 100%!important;
            background-color: #999!important;
        }
        &:after{
            width: 0%!important;
            background-color: #fff!important; 
        }
        &:hover:after{
            width: 100%!important;
        }
    }
    header.scroll{
        a.navigation__link {
            &:before{
               background-color: #ddd!important;
            }
            &:hover:after{
               background-color: #2A505D!important; 
            }
        }
    }
}
/*END - header nav link underline */

/*START - change nav background color by WB  */
nav#global-navbar header.header{
    .navigation__item.sub-nav-container .sub-nav{
    background-color:#fff;
        ul li .nav-link{
            text-transform: uppercase;
            color:#000;
            &:hover{
                background-color:#000;
                color: #fff;
            }
        }
    }
    div.header__container{
       border-bottom: 2px solid rgba(255, 255, 255, 0.49); 
    }
    &.scroll{
        background-color:#000;
        color: #fff;
        button.hamburger{
            &:before, &:after{
                border-color: #fff;
            }
        }
        div.header__container{
           border-bottom: 2px solid #000; 
        }
    }
}
/*END - change nav background color*/

/* Header, Make dark logo appears on scroll - WB */
nav#global-navbar header.header {
    img.logo__img--light{
        display: block!important;
    }
    img.logo__img--dark{
        display: none!important;
    }
}
/* END */

/*Fix header logo size in mobile view - WB  */
@media (max-width: 578px) {
    nav#global-navbar .logo img {
        max-width: 230px;
    }
}
/*END*/

/*Change to uppercase sidemenu items by WB */
div#global-sidemenu .sidemenu__nav {
    li.sidemenu__item .sidemenu__grouped {
        text-transform: uppercase;
    }
    li a{
        text-transform: uppercase;
    }
}
/*END*/

/*Center Social Icons in Footer, SideMenu & Contact Overlay - WB */
@media (max-width: 678px) {
    div#global-sidemenu .lp-socials {
        justify-content: center!important;
        li{
            margin: 10px 10px 0 10px!important;
        }
    }

    footer#global-footer .lp-socials{
        justify-content: center!important;
        li{
            margin: 10px 10px 0 10px!important;
        }
    }
    div#modal-global-contact-us .lp-socials{
        justify-content: center!important;
        li{
            margin: 10px 10px 0 10px!important;
        }
    }
}
/*END*/

/*START - Contact form link underline - WB */
div#modal-global-contact-us{
    div.contact-popup__info a {
        position: relative!important;
        &:before, &:after{
            transition: 0.4s;
            text-decoration: none!important;
            line-height: 1;
            content: """";
            height: 1px;
            position: absolute!important;
            bottom: 0;
            left: 0;
        }
        &:before {
            width: 100%!important;
            background-color: #ddd!important;
        }
        &:after{
            width: 0%!important;
            background-color: #63666F!important; 
        }
        &:hover{
            color: #63666F!important;
        }
        &:hover:after{
            width: 100%!important;
        }
    }
}
/*END - link underline*/

/*START - Footer - add line to hyperlink by WB  */
.footer__disclaimer a,.footer__info-column a,.footer__copyright a,a.hyperlink-style-2,.footer__menu a{
    position: relative;
    display: inline-block;
    vertical-align: top;
    &:after, &:before{
        content: """";
        height: 1px;
        position: absolute;
        bottom: 0;
        left: 0;
        box-sizing: border-box;
        outline: none;
        transition: 0.4s;
    }
    &:before{
        background-color: #ccc;
        width: 100%;
    }
    &:after{
        width: 0%;
        background-color: #FFFFFF;
        transition: 0.4s;
    }
    &:hover{
        text-decoration: none!important;
        &:after{
            width: 100%;
        }
    }
}
footer#global-footer{
    .footer__disclaimer{
        opacity: 1;
    }
    .footer__copyright .link {
        text-decoration: none;
    }
    .footer__menu-item {
        text-transform: uppercase;
    }
}
/*END - add line to hyperlink*/

/* Header, Increase Logo size - WB */
footer#global-footer .footer__info-column {
    .footer__logo{
        max-height: 300px;
        max-width: 400px;
    }
    margin-bottom: 0px;
}
/* END */

/* Gallery style menu theme - WB */
div.gallery-component__col .gallery-card__title {
  text-align: center;
  font-size: 26px;
  text-transform: none;
  margin-top: auto;
  margin-bottom: auto;
  padding-bottom: 20px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

/*GSM Ipad view - Producer - WB Nicolas V*/
@media(min-width: 765px) and (max-width: 1025px) {
    div.gallery-component__col .gallery-card__title {
        font-size: 24px!important;
    }
}
/*END*/


div.gallery-component__col .gallery-card {
  position: relative;
  width: 100%;
  padding-right: 20px;
  padding-left: 20px;
  height: 350px;
  &::before {
    background-image: linear-gradient(
      to bottom,
      rgba(0, 0, 0, 0),
      rgba(0, 0, 0, 0.95)
    ) !important;
  }
}

@media (max-width: 768px) {
  div.gallery-component__col .gallery-card {
    position: relative;
    width: 100%;
    padding-right: 0px;
    padding-left: 0px;
    height: 310px;
  }
  div.row.gallery-component__row.cols-3 .gallery-component__col {
    max-width: 100%;
    flex-basis: 100%;
    padding-right: 10px;
    padding-left: 10px;
  }
}
/*END - Gallery style menu*/

/*START - fix gsm padding - WB Nicolas V */
div.gallery-component {
    padding-top:96px;
    padding-bottom: 46px;
    @media (max-width: 768px){
        padding-bottom: 44px;
